function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}function dateStr(d){return d.toISOString().slice(0,10)}
let activePreset=null;
function presetChoices(){return isDaily?[['dailyToday','today'],['dailyYesterday','yesterday'],['dailyYesterdayToday','yesterdayToday'],['dailyMonth','month'],['dailyLastMonth','last'],['daily7','7'],['daily30','30'],['daily60','60']]:[['today','today'],['yesterday','yesterday'],['yesterdayToday','yesterdayToday'],['thisMonth','month'],['lastMonth','last'],['last7','7'],['last30','30'],['last60','60']];}
function presetRange(type){const end=today(),d=new Date(end+'T12:00:00Z');let from=end,to=end;if(type==='month')from=end.slice(0,8)+'01';if(type==='last'){d.setUTCDate(0);to=dateStr(d);from=to.slice(0,8)+'01';}if(['7','30','60'].includes(type)){d.setUTCDate(d.getUTCDate()-(Number(type)-1));from=dateStr(d);}if(type==='yesterday'||type==='yesterdayToday'){d.setUTCDate(d.getUTCDate()-1);from=dateStr(d);if(type==='yesterday')to=from;}return{from,to};}
function paintPreset(type,animate=false){activePreset=type;for(const[id,value]of presetChoices()){const button=$(id);if(!button)continue;button.setAttribute('aria-pressed',String(value===type));button.dataset.preset=value;if(animate&&value===type){button.classList.remove('preset-pulse');void button.offsetWidth;button.classList.add('preset-pulse');}}}
