function mergeInventoryDays(records){const days=new Map(),fields=['dailyCenterInventoryQty','shipIn','returnShipIn','faultyShipIn','damageShipIn','transferShipin','shipOut','transferShipout'];for(const item of records){const key=String(item.ymd);if(!/^\d{8}$/.test(key))throw Error('재고 기록의 일자 형식이 변경되었습니다.');let day=days.get(key);if(!day){day={skuNo:item.skuNo,ymd:key};for(const field of fields)day[field]=0;days.set(key,day);}for(const field of fields){const n=Number(item[field]||0);if(!Number.isFinite(n))throw Error('재고 기록의 수량 형식이 변경되었습니다.');day[field]+=n;}}return [...days.values()];}
