async function resolveChannel(log,end,signal,sku,from){assertActive(signal);const memo=log.memo||'',channelNo=memo.match(/판매채널주문번호:([^,]+)/)?.[1]?.trim(),tracking=memo.match(/송장번호:([^,]+)/)?.[1]?.trim(),delivery=memo.match(/배송번호:([^,]+)/)?.[1]?.trim();const key=[delivery,channelNo,tracking,sku,log.date,log.qty].join('|');if(channelCache.has(key))return channelCache.get(key);
if(channelNo||tracking){const p=new URLSearchParams({page:'1',searchLength:'100',orderStatus:'',startDate:'20000101',endDate:end.replaceAll('-','')});if(channelNo)p.set('channelOrderNo',channelNo);else p.set('trackingNo',tracking);let rows=(await orderRows(p,signal)).filter(r=>channelNo?r.cells[4]===channelNo:r.cells[8]===tracking);let exact=tracking?rows.filter(r=>r.cells[8]===tracking):rows;if(!exact.length)exact=rows;const names=[...new Set(exact.map(r=>r.cells[2]).filter(Boolean))];if(names.length===1){channelCache.set(key,names[0]);return names[0];}}
const rows=await fallbackOrders(from,end,signal);const candidates=rows.filter(r=>channelNo?r.cells[4]===channelNo:tracking?r.cells[8]===tracking:!r.cells[4]||r.cells[4]==='-');const proved=[];for(const candidate of candidates){const proof=await shipmentProof(candidate.orderNo,signal);const actualDate=String(log.date).replace(/\D/g,'');const qty=proof.items.filter(i=>i.sku===String(sku)).reduce((sum,i)=>sum+i.qty,0);if(proof.date===actualDate&&qty===Number(log.qty)&&proof.channel)proved.push(proof.channel);}const names=[...new Set(proved)];const name=names.length===1?names[0]:null;if(name)channelCache.set(key,name);return name;}
