  if(doc.title.includes('로그인'))throw Error('위킵 로그인 세션이 만료되었습니다.');
  if(pageNo===1){const match=html.match(/setPageNavigation\('pageNavigation',\s*(\d+),/);expected=match?Number(match[1]):null;}
  const rows=[...doc.querySelectorAll('#orderItemList tr[orderNo]')].map(tr=>{const c=[...tr.querySelectorAll('td')].map(td=>td.textContent.trim());return {orderNo:tr.getAttribute('orderNo'),state:c[10]||'',channel:c[2]||''};});
  all.push(...rows);
  $('status').textContent=(state?'미출고 배정 검증':'등록일 기준 주문 목록')+' · '+all.length+(expected!==null?'/'+expected:'')+'건';
  if(rows.length<100||(expected!==null&&all.length>=expected))break;
