 await pool(list,async item=>{const record=await registeredOrderRecord(item.orderNo,signal,cache);assertActive(signal);if(record.shipoutDate||record.state.includes('취소')||!record.state.includes('상품준비중'))return;for(const i of record.items){if(!i.sku||!i.qty)continue;(preparing[i.sku]||= []).push({channel:record.channel,qty:i.qty});}},3);
