  $('status').textContent=row.name+' · 현재 가용재고와 배정 대기 '+fmt(row.pendingRaw)+'개 대조';
  const d=await request('/fbw/admin/v2/inventory/inventoryHistory',{page:1,skuNo:row.sku,startDate:today().replaceAll('-',''),endDate:today().replaceAll('-','')},signal);
