async function requestFresh(url,options,signal){for(let attempt=0;attempt<4;attempt++){assertActive(signal);let response,payload;try{const read=await mdRequest(url,{...options,cache:'no-store',signal});response=read.response;payload=read.payload;}catch(error){if(signal.aborted||error.name==='AbortError'||error.name==='MdTimeoutError')throw error;if(attempt===3)throw Error('위킵 연결이 반복해서 끊겼습니다. 인터넷 연결을 확인해 주세요.');await delayLookup(500*2**attempt,signal);continue;}if([408,429,500,502,503,504].includes(response.status)&&attempt<3){const header=Number(response.headers.get('Retry-After')),wait=Number.isFinite(header)&&header>0?Math.min(10000,header*1000):500*2**attempt;await delayLookup(wait,signal);continue;}if(!response.ok)throw Error('위킵 조회 실패 ('+response.status+')');assertActive(signal);return{status:response.status,headers:response.headers,text:async()=>payload,json:async()=>JSON.parse(payload)};}throw Error('위킵 연결 재시도 실패');}
