    if (record.day < from || record.day > to) continue;
    const isCancelled = record.cancelled || (/취소|cancel/i.test(record.state) && !/부분|partial/i.test(record.state));
    if (isCancelled) {
      if (!keyword || matched.length) cancelled = add(cancelled, 1);
      for (const item of matched) cancelledQty = add(cancelledQty, item.qty);
      continue;
    }
    if (!matched.length) continue;
    orders = add(orders, 1);
    const channel = typeof record.channel === 'string' && record.channel.trim() ? record.channel : '판매처 미확인';
    const status = statusOf(record);
